<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { useGrammarAudio } from '../../../composables/useGrammarAudio.js';

const emit=defineEmits(['salir','alimento']);
const { reproducirTexto, reiniciarAudio }=useGrammarAudio();
const grupos={
  present:[{id:'habit',icono:'🔁',nombre:'Rutina',pista:'presente simple'},{id:'now',icono:'🔴',nombre:'Ahora',pista:'presente continuo'},{id:'state',icono:'💭',nombre:'Estado',pista:'verbo no continuo'},{id:'arranged',icono:'📆',nombre:'Plan acordado',pista:'continuo con futuro'}],
  past:[{id:'finished',icono:'📍',nombre:'Terminó',pista:'pasado simple'},{id:'progress',icono:'🎬',nombre:'En progreso',pista:'pasado continuo'},{id:'result',icono:'🌉',nombre:'Resultado ahora',pista:'presente perfecto'},{id:'paststate',icono:'📸',nombre:'Estado pasado',pista:'was / were'}],
  future:[{id:'intention',icono:'🧭',nombre:'Plan decidido',pista:'going to'},{id:'instant',icono:'💡',nombre:'Decisión ahora',pista:'will'},{id:'evidence',icono:'☁️',nombre:'Evidencia',pista:'going to'},{id:'offer',icono:'🍵',nombre:'Oferta',pista:'shall'}],
  modals:[{id:'ability',icono:'💪',nombre:'Habilidad',pista:'can'},{id:'polite',icono:'🤝',nombre:'Pedido cortés',pista:'could'},{id:'obligation',icono:'🔒',nombre:'Obligación',pista:'must / have to'},{id:'advice',icono:'🧭',nombre:'Consejo',pista:'should'}],
  voice:[{id:'active',icono:'👤',nombre:'Voz activa',pista:'quién hace la acción'},{id:'passive-now',icono:'🔄',nombre:'Pasiva presente',pista:'is / are + participio'},{id:'passive-past',icono:'📜',nombre:'Pasiva pasada',pista:'was / were + participio'},{id:'instruction',icono:'🪧',nombre:'Instrucción',pista:'imperativo'}],
};
const banco=[
  {grupo:'present',icono:'☕',frase:'I drink coffee every morning.',respuesta:'habit',explicacion:'Every morning señala una rutina: presente simple.'},
  {grupo:'present',icono:'📖',frase:'She is reading right now.',respuesta:'now',explicacion:'Right now muestra una acción en progreso.'},
  {grupo:'present',icono:'🧠',frase:'They know the answer.',respuesta:'state',explicacion:'Know describe un estado y normalmente no va en continuo.'},
  {grupo:'present',icono:'🍽️',frase:"We're meeting Ana at 8 PM.",respuesta:'arranged',explicacion:'La hora concreta muestra un plan ya acordado.'},
  {grupo:'past',icono:'🏛️',frase:'We visited the museum yesterday.',respuesta:'finished',explicacion:'Yesterday ubica una acción terminada.'},
  {grupo:'past',icono:'🍲',frase:'I was cooking when you called.',respuesta:'progress',explicacion:'Was cooking era la acción en progreso.'},
  {grupo:'past',icono:'🧹',frase:'I have cleaned the kitchen, so we can cook now.',respuesta:'result',explicacion:'Importa el resultado presente: la cocina está limpia ahora.'},
  {grupo:'past',icono:'🏖️',frase:'They were on vacation last week.',respuesta:'paststate',explicacion:'Were describe un estado o ubicación pasada.'},
  {grupo:'future',icono:'🎟️',frase:"We've bought the tickets. We're going to travel.",respuesta:'intention',explicacion:'Los boletos prueban que el plan ya estaba decidido.'},
  {grupo:'future',icono:'📞',frase:"The phone is ringing. I'll answer it.",respuesta:'instant',explicacion:'La decisión nace en el momento de hablar.'},
  {grupo:'future',icono:'🌧️',frase:"Look at those clouds! It's going to rain.",respuesta:'evidence',explicacion:'Las nubes son evidencia visible para la predicción.'},
  {grupo:'future',icono:'🍵',frase:'Shall I make some tea?',respuesta:'offer',explicacion:'Shall I…? se usa para ofrecer algo.'},
  {grupo:'modals',icono:'🏊',frase:'Marta can swim very well.',respuesta:'ability',explicacion:'Can expresa una habilidad.'},
  {grupo:'modals',icono:'🪟',frase:'Could you open the window, please?',respuesta:'polite',explicacion:'Could you…? formula un pedido cortés.'},
  {grupo:'modals',icono:'🚗',frase:'You must wear a seat belt.',respuesta:'obligation',explicacion:'Must expresa obligación fuerte.'},
  {grupo:'modals',icono:'😴',frase:'You should go to bed earlier.',respuesta:'advice',explicacion:'Should presenta una recomendación.'},
  {grupo:'voice',icono:'👩‍🍳',frase:'My mother bakes the bread every morning.',respuesta:'active',explicacion:'El sujeto —my mother— realiza la acción.'},
  {grupo:'voice',icono:'🍞',frase:'The bread is baked every morning.',respuesta:'passive-now',explicacion:'Is + baked forma la pasiva en presente.'},
  {grupo:'voice',icono:'🧱',frase:'The walls were painted last year.',respuesta:'passive-past',explicacion:'Were + painted forma la pasiva en pasado.'},
  {grupo:'voice',icono:'🚪',frase:'Close the door, please.',respuesta:'instruction',explicacion:'La frase empieza con el verbo base: es un imperativo.'},
];

const ronda=ref(0),vidas=ref(3),racha=ref(0),ganadas=ref(0),estado=ref(''),elegido=ref(null),arrastrando=ref(false),toqueInicio=ref(null);
const ejercicio=computed(()=>banco[ronda.value%banco.length]),portales=computed(()=>grupos[ejercicio.value.grupo]),progreso=computed(()=>Math.round(((ronda.value+1)/banco.length)*100)),portalCorrecto=computed(()=>portales.value.find(x=>x.id===ejercicio.value.respuesta));

function clasificar(id){if(estado.value)return;elegido.value=id;if(id===ejercicio.value.respuesta){estado.value='correcto';racha.value+=1;ganadas.value+=1;emit('alimento',1);reproducirTexto(ejercicio.value.frase)}else{vidas.value-=1;racha.value=0;estado.value=vidas.value<=0?'agotado':'incorrecto'}}
function siguiente(){ronda.value=(ronda.value+1)%banco.length;estado.value='';elegido.value=null;arrastrando.value=false;reiniciarAudio()}
function reiniciar(){ronda.value=0;vidas.value=3;racha.value=0;ganadas.value=0;estado.value='';elegido.value=null;reiniciarAudio()}
function teclado(event){if(estado.value||event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)return;if(/^[1-4]$/.test(event.key))clasificar(portales.value[Number(event.key)-1].id)}
function iniciarDrag(event){arrastrando.value=true;event.dataTransfer?.setData('text/plain','grammar-card');if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function soltar(id){if(arrastrando.value)clasificar(id);arrastrando.value=false}
function iniciarToque(event){const t=event.touches?.[0];arrastrando.value=true;toqueInicio.value=t?{x:t.clientX,y:t.clientY}:null}
function terminarToque(event){const t=event.changedTouches?.[0];const portal=t?document.elementFromPoint(t.clientX,t.clientY)?.closest('[data-portal]'):null;const distancia=t&&toqueInicio.value?Math.hypot(t.clientX-toqueInicio.value.x,t.clientY-toqueInicio.value.y):Infinity;if(portal)clasificar(portal.dataset.portal);else if(distancia<12)arrastrando.value=false;arrastrando.value=false;toqueInicio.value=null}
onMounted(()=>window.addEventListener('keydown',teclado));onUnmounted(()=>{window.removeEventListener('keydown',teclado);reiniciarAudio()});
</script>

<template><section class="sort-game"><header><button @click="emit('salir')">← Centro de juegos</button><span>GRAMMAR SORT · {{ronda+1}} DE {{banco.length}}</span><b>🔥 {{racha}} · 🍎 {{ganadas}}</b></header><div class="progress"><i :style="{width:progreso+'%'}"></i></div><div class="status"><span>{{'❤️'.repeat(vidas)}}{{'♡'.repeat(3-vidas)}}</span><small>Teclas 1–4 · toque o arrastre</small></div>
<div class="arena"><div class="card-wrap"><div class="card" draggable="true" :class="{dragging:arrastrando}" @dragstart="iniciarDrag" @dragend="arrastrando=false" @touchstart.passive="iniciarToque" @touchend.prevent="terminarToque"><span>{{ejercicio.icono}}</span><small>CLASIFICÁ ESTA FRASE</small><h2>{{ejercicio.frase}}</h2><button @click.stop="reproducirTexto(ejercicio.frase)">🔊 Escuchar</button><em>Arrastrame hacia un portal</em></div></div><div class="portals"><button v-for="(portal,i) in portales" :key="portal.id" :data-portal="portal.id" :class="{correct:estado&&portal.id===ejercicio.respuesta,wrong:elegido===portal.id&&estado!=='correcto'}" @click="clasificar(portal.id)" @dragover.prevent @drop.prevent="soltar(portal.id)"><small>{{i+1}}</small><span>{{portal.icono}}</span><b>{{portal.nombre}}</b><em>{{portal.pista}}</em></button></div></div>
<div v-if="estado" class="feedback" :class="estado==='correcto'?'ok':'retry'"><b>{{estado==='correcto'?'✓ ¡Portal correcto!':estado==='agotado'?'💫 Se acabaron las vidas':'↻ Ese portal no corresponde'}}</b><span>{{ejercicio.explicacion}}</span><small>Respuesta: {{portalCorrecto.icono}} {{portalCorrecto.nombre}}</small></div><footer><button class="secondary" @click="emit('salir')">Salir</button><button v-if="estado==='agotado'" class="primary" @click="reiniciar">Reiniciar ruta</button><button v-else-if="estado" class="primary" @click="siguiente">Siguiente tarjeta →</button></footer></section></template>

<style scoped>
.sort-game{padding:1.2rem;border:1px solid var(--color-borde);border-radius:20px;background:var(--color-superficie);box-shadow:var(--sombra-card)}header{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:.7rem}header>button{border:0;background:none;color:var(--color-azul);text-align:left}header>span{font-size:.67rem;font-weight:900;letter-spacing:.08em;color:#7655a5}header>b{text-align:right;color:#9b641b}.progress{height:7px;margin:.7rem 0;border-radius:99px;background:#e8eee9;overflow:hidden}.progress i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#7655a5,#e68c54);transition:.3s}.status{display:flex;justify-content:space-between;padding:.6rem .8rem;border-radius:10px;background:var(--color-fondo-suave);font-size:.75rem}.status small{color:var(--color-texto-tenue)}.arena{margin-top:.8rem;padding:1rem;border-radius:18px;background:radial-gradient(circle at 50% 15%,#fff7df,#edf3fb 65%,#eee9f8)}.card-wrap{display:grid;place-items:center;min-height:210px}.card{display:flex;flex-direction:column;align-items:center;width:min(100%,510px);padding:1.1rem;border:2px solid #c7b8dc;border-radius:18px;background:#fff;box-shadow:0 10px 24px #4b37671c;text-align:center;cursor:grab;touch-action:none}.card.dragging{opacity:.55;transform:scale(.97)}.card>span{font-size:2.7rem}.card>small{font-size:.6rem;font-weight:900;letter-spacing:.08em;color:#7655a5}.card h2{margin:.35rem;font:italic 1.2rem Georgia}.card button{padding:.4rem .65rem;border:0;border-radius:8px;background:#7655a5;color:#fff}.card em{margin-top:.4rem;font-size:.65rem;color:var(--color-texto-tenue)}.portals{display:grid;grid-template-columns:repeat(4,1fr);gap:.55rem}.portals button{position:relative;display:flex;flex-direction:column;align-items:center;min-height:125px;padding:.8rem .4rem;border:2px solid transparent;border-radius:15px;background:#ffffffd9;box-shadow:0 4px 12px #26354a12}.portals button>small{position:absolute;top:-7px;left:-7px;display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#293c55;color:#fff;font-weight:900}.portals button>span{font-size:2rem}.portals button>b{font-size:.78rem}.portals button>em{font-size:.62rem;color:var(--color-texto-tenue)}.portals button.correct{border-color:var(--color-verde);background:var(--color-verde-suave);animation:pulse .35s}.portals button.wrong{border-color:var(--color-rojo);background:var(--color-rojo-suave);animation:shake .25s}.feedback{display:flex;flex-direction:column;margin-top:.8rem;padding:.75rem;border-radius:11px}.feedback.ok{background:var(--color-verde-suave);color:var(--color-verde)}.feedback.retry{background:var(--color-rojo-suave);color:var(--color-rojo)}.feedback small{margin-top:.25rem}footer{display:flex;justify-content:center;gap:.7rem;margin-top:1rem}footer button{min-width:170px;padding:.75rem;border-radius:var(--radio-boton);font-weight:800}.primary{border:0;background:#7655a5;color:#fff}.secondary{border:1px solid var(--color-borde);background:#fff}@keyframes shake{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}@keyframes pulse{50%{transform:scale(1.03)}}
@media(max-width:700px){.sort-game{padding:.8rem}header{grid-template-columns:1fr auto}header>span{grid-row:2;grid-column:1/-1}.portals{grid-template-columns:1fr 1fr}.card-wrap{min-height:190px}}@media(max-width:430px){.portals{grid-template-columns:1fr}.portals button{min-height:90px}.arena{padding:.7rem}footer{flex-direction:column}footer button{width:100%}}
</style>
